/** Windows-local follow-up to the actual first revised story PNGs. No rendering/audio/network here. */
import fs from 'node:fs/promises';import path from 'node:path';import {createHash} from 'node:crypto';import {gunzipSync} from 'node:zlib';
const root=process.cwd(),prefix='src/v2/episodes/in-this-town-02/',out='out/v2-episodes/in-this-town-02/';
const hash=s=>createHash('sha256').update(s.replaceAll('\r\n','\n')).digest('hex');
const read=async name=>fs.readFile(path.join(root,name)).catch(e=>{if(e.code==='ENOENT')return null;throw e;});
const payload=JSON.parse(gunzipSync(Buffer.from('','base64')).toString('utf8'));
const guards={"src/v2/episodes/in-this-town-02/timeline.ts":"ada42afe8cca64a74ed9f5f94dd7af2b25e2202f4bce661408a18ffb731aa075","src/v2/episodes/in-this-town-02/catBehaviors.ts":"05567b470ddecbb04658c0c428ed4fb3bf8ac21e6dd46a0b414e7160cc068736","src/v2/episodes/in-this-town-02/PRODUCTION_DIRECTOR_LOCK.json":"806789d990db63b5118bbc0d4c887b87d8bec7da6d46d4e6ef061e9f112b4e7d"};
const originals=new Map(),writes=new Map(),mismatches=[],preservedNotes=[];
for(const [name,expected] of Object.entries(guards)){const raw=await read(name);if(!raw||hash(raw.toString('utf8'))!==expected)mismatches.push(name);}
for(const [name,p] of Object.entries(payload)){
 if(!name.startsWith(prefix)||name.split('/').includes('..')||hash(p.text)!==p.after)throw Error('Invalid repair payload');
 const raw=await read(name),actual=raw===null?null:hash(raw.toString('utf8'));if(actual===p.after)continue;
 if(actual!==p.before){if(name.endsWith('.md')){preservedNotes.push(name);continue;}mismatches.push(name);continue;}
 originals.set(name,raw);writes.set(name,Buffer.from(p.text));
}
if(mismatches.length)throw Error('Local source differs: '+mismatches.join(', ')+'. No files changed. Preserve and reconcile these files first.');
const json=async name=>{const b=await read(name);if(!b)throw Error('Missing existing local file '+name+'. No files changed.');return JSON.parse(b.toString('utf8'));};
const props=await json(out+'render-props.json');
if(props.audioApproved!==true||props.shots?.length!==62||props.shots.at(-1).end!==3737)throw Error('Approved edit differs from the reviewed 62-segment/3737-frame source. No files changed.');
const installName=out+'STORY_DIRECTION_INSTALL.json',install=await json(installName),statusName=out+'VISIBILITY_REPAIR_INSTALL.json';
if(!writes.size&&await read(statusName)){console.log('Visibility follow-up already installed. Run tools/review-visibility-fix.mjs.');process.exit(0);}
const sources=Object.fromEntries(Object.entries(payload).filter(([n])=>!preservedNotes.includes(n)).map(([n,p])=>[n,p.after]));
const status={stage:'VISIBILITY_SOURCE_CORRECTED__LOCAL_PNG_AND_MOTION_REVIEW_PENDING',visualApproval:false,frames:3737,segments:62,preservedLocalNotes:preservedNotes,sources,paidNarrationRequests:0,rendering:false};
for(const [name,value] of [[installName,{...install,stage:status.stage,visualApproval:false,sources:{...install.sources,...sources}}],[statusName,status]]){originals.set(name,await read(name));writes.set(name,Buffer.from(JSON.stringify(value,null,2)+'\n'));}
console.log(JSON.stringify({stage:'VISIBILITY_REPAIR_INPUTS_VERIFIED',files:[...writes.keys()],preservedLocalNotes:preservedNotes,rendering:false,paidRequests:0},null,2));
if(!process.argv.includes('--apply')){console.log('Dry run only. Add --apply to install with backups.');process.exit(0);}
const backup=path.join(root,out,'visibility-repair-backup-'+Date.now());await fs.mkdir(backup,{recursive:true});
for(const [name,bytes] of originals)if(bytes){const p=path.join(backup,name);await fs.mkdir(path.dirname(p),{recursive:true});await fs.writeFile(p,bytes);}
await fs.writeFile(path.join(backup,'RESTORE_MANIFEST.json'),JSON.stringify({created:[...originals].filter(([,b])=>b===null).map(([n])=>n),replaced:[...originals].filter(([,b])=>b!==null).map(([n])=>n)},null,2)+'\n');
for(const [name,bytes] of originals){const now=await read(name);if((now===null)!==(bytes===null)||(now&&bytes&&!now.equals(bytes)))throw Error('File changed during backup: '+name+'. No source files written.');}
try{for(const [name,bytes] of writes){const p=path.join(root,name);await fs.mkdir(path.dirname(p),{recursive:true});await fs.writeFile(p,bytes);}for(const [name,bytes] of writes){if(!(await read(name))?.equals(bytes))throw Error('Write verification failed: '+name);}}
catch(error){for(const [name,bytes] of originals){if(bytes)await fs.writeFile(path.join(root,name),bytes);else await fs.rm(path.join(root,name),{force:true});}throw error;}
console.log('Installed. Backups: '+backup);
console.log('Next: node src/v2/episodes/in-this-town-02/tools/review-visibility-fix.mjs');
